const rows = $input.all().map(item => item.json);

const today = $now.setZone('Europe/Paris').toFormat('dd/MM/yyyy');

return [
  {
    json: {
      date: today,
      nombre_entrees: rows.length,
      entrees_du_jour: rows
    }
  }
];

const recapNodeName = 'Code — Préparer entrées du jour';
const memoireNodeName = 'Google Sheets : lire Projets_Memoire';

const recap = $(recapNodeName).first().json;

const memoireProjets = $(memoireNodeName)
  .all()
  .map(item => item.json)
  .filter(row => row.projet);

return [
  {
    json: {
      date: recap.date,
      nombre_entrees: recap.nombre_entrees || 0,
      entrees_du_jour: recap.entrees_du_jour || [],
      memoire_projets: memoireProjets,
      entrees_du_jour_json: JSON.stringify(recap.entrees_du_jour || [], null, 2),
      memoire_projets_json: JSON.stringify(memoireProjets, null, 2)
    }
  }
];

let raw =
  $json.output ||
  $json.text ||
  $json.message?.content ||
  $json.choices?.[0]?.message?.content ||
  $json.response ||
  '';

raw = String(raw)
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(raw);
} catch (error) {
  parsed = {
    objet_mail: `Récap Direction IA — ${$('Code — Construire contexte récap').first().json.date}`,
    titre: `Récap Direction IA — ${$('Code — Construire contexte récap').first().json.date}`,
    date: $('Code — Construire contexte récap').first().json.date,
    resume_executif: raw || "Le récap IA n’a pas pu être parsé correctement.",
    discussions_du_jour: [],
    points_evolution_notes: [],
    concordance_idees: [],
    points_non_clotures: [
      {
        projet: "Global",
        point: "Erreur de parsing JSON",
        raison: "La réponse IA n’était pas un JSON valide.",
        prochaine_action_recommandee: "Vérifier le prompt ou relancer le workflow."
      }
    ],
    actions_prioritaires: [],
    maj_memoire_proposees: [],
    conclusion_direction: "Récap généré avec erreur de format."
  };
}

return [
  {
    json: parsed
  }
];

const recap = $json;

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function safeArray(value) {
  return Array.isArray(value) ? value : [];
}

function priorityColor(priority) {
  const p = String(priority || '').toLowerCase();

  if (p === 'haute' || p === 'haut') {
    return {
      bg: '#FEE2E2',
      color: '#991B1B',
      border: '#FCA5A5',
      label: 'Haute'
    };
  }

  if (p === 'moyenne' || p === 'moyen') {
    return {
      bg: '#FEF3C7',
      color: '#92400E',
      border: '#FCD34D',
      label: 'Moyenne'
    };
  }

  return {
    bg: '#DBEAFE',
    color: '#1E40AF',
    border: '#93C5FD',
    label: 'Basse'
  };
}

function alignmentBadge(value) {
  const v = String(value || '').toLowerCase();

  if (v === 'fort') {
    return `<span style="display:inline-block;padding:6px 10px;border-radius:999px;background:#DCFCE7;color:#166534;font-size:12px;font-weight:700;">Alignement fort</span>`;
  }

  if (v === 'moyen') {
    return `<span style="display:inline-block;padding:6px 10px;border-radius:999px;background:#FEF3C7;color:#92400E;font-size:12px;font-weight:700;">Alignement moyen</span>`;
  }

  return `<span style="display:inline-block;padding:6px 10px;border-radius:999px;background:#FEE2E2;color:#991B1B;font-size:12px;font-weight:700;">Alignement faible</span>`;
}

function projectBadge(project) {
  return `<span style="display:inline-block;padding:6px 10px;border-radius:999px;background:#EFF6FF;color:#1D4ED8;font-size:12px;font-weight:700;border:1px solid #BFDBFE;">${escapeHtml(project || 'Global')}</span>`;
}

function emptyBlock(text = 'Aucun élément relevé.') {
  return `
    <tr>
      <td style="padding:14px 16px;background:#F8FAFC;border:1px solid #E2E8F0;border-radius:14px;color:#64748B;font-size:14px;">
        ${escapeHtml(text)}
      </td>
    </tr>
  `;
}

function sectionTitle(title, subtitle) {
  return `
    <tr>
      <td style="padding:28px 0 12px 0;">
        <h2 style="margin:0;color:#0F172A;font-size:20px;line-height:1.3;font-weight:800;">
          ${escapeHtml(title)}
        </h2>
        ${subtitle ? `
          <p style="margin:6px 0 0 0;color:#64748B;font-size:14px;line-height:1.5;">
            ${escapeHtml(subtitle)}
          </p>
        ` : ''}
      </td>
    </tr>
  `;
}

const discussions = safeArray(recap.discussions_du_jour);
const evolutions = safeArray(recap.points_evolution_notes);
const concordances = safeArray(recap.concordance_idees);
const nonClotures = safeArray(recap.points_non_clotures);
const actions = safeArray(recap.actions_prioritaires);
const majMemoire = safeArray(recap.maj_memoire_proposees);

const discussionsHtml = discussions.length
  ? discussions.map(item => `
      <tr>
        <td style="padding:16px;background:#FFFFFF;border:1px solid #E2E8F0;border-radius:16px;">
          <div style="margin-bottom:10px;">
            ${projectBadge(item.projet)}
          </div>
          <h3 style="margin:0 0 8px 0;color:#0F172A;font-size:16px;line-height:1.4;font-weight:800;">
            ${escapeHtml(item.sujet)}
          </h3>
          <p style="margin:0 0 10px 0;color:#334155;font-size:14px;line-height:1.6;">
            ${escapeHtml(item.resume)}
          </p>
          <p style="margin:0;color:#64748B;font-size:13px;line-height:1.5;">
            Auteur(s) : ${escapeHtml(safeArray(item.auteurs_impliques).join(', ') || 'Non précisé')}
          </p>
        </td>
      </tr>
      <tr><td style="height:10px;"></td></tr>
    `).join('')
  : emptyBlock('Aucune discussion exploitable relevée aujourd’hui.');

const evolutionsHtml = evolutions.length
  ? evolutions.map(item => {
      const badge = priorityColor(item.importance);
      return `
        <tr>
          <td style="padding:16px;background:#FFFFFF;border:1px solid #E2E8F0;border-radius:16px;">
            <div style="margin-bottom:10px;">
              ${projectBadge(item.projet)}
              <span style="display:inline-block;margin-left:6px;padding:6px 10px;border-radius:999px;background:${badge.bg};color:${badge.color};border:1px solid ${badge.border};font-size:12px;font-weight:700;">
                Importance ${escapeHtml(badge.label)}
              </span>
            </div>
            <p style="margin:0 0 8px 0;color:#0F172A;font-size:15px;line-height:1.6;font-weight:700;">
              ${escapeHtml(item.idee)}
            </p>
            <p style="margin:0 0 6px 0;color:#334155;font-size:14px;line-height:1.6;">
              Impact potentiel : ${escapeHtml(item.impact_potentiel)}
            </p>
            <p style="margin:0;color:#64748B;font-size:13px;">
              Évoqué par : ${escapeHtml(item.auteur || 'Non précisé')}
            </p>
          </td>
        </tr>
        <tr><td style="height:10px;"></td></tr>
      `;
    }).join('')
  : emptyBlock('Aucun point d’évolution notable détecté.');

const concordanceHtml = concordances.length
  ? concordances.map(item => `
      <tr>
        <td style="padding:16px;background:#FFFFFF;border:1px solid #E2E8F0;border-radius:16px;">
          <div style="margin-bottom:10px;">
            ${projectBadge(item.projet)}
            <span style="margin-left:6px;">${alignmentBadge(item.alignement_avec_objectif)}</span>
          </div>
          <p style="margin:0 0 10px 0;color:#334155;font-size:14px;line-height:1.6;">
            ${escapeHtml(item.analyse)}
          </p>
          <div style="padding:12px 14px;border-radius:12px;background:#EFF6FF;border:1px solid #BFDBFE;">
            <p style="margin:0;color:#1E3A8A;font-size:14px;line-height:1.6;font-weight:700;">
              Suggestion direction :
            </p>
            <p style="margin:4px 0 0 0;color:#1E40AF;font-size:14px;line-height:1.6;">
              ${escapeHtml(item.suggestion_direction)}
            </p>
          </div>
        </td>
      </tr>
      <tr><td style="height:10px;"></td></tr>
    `).join('')
  : emptyBlock('Aucune concordance stratégique significative détectée.');

const nonCloturesHtml = nonClotures.length
  ? nonClotures.map(item => `
      <tr>
        <td style="padding:16px;background:#FFF7ED;border:1px solid #FDBA74;border-radius:16px;">
          <div style="margin-bottom:10px;">
            ${projectBadge(item.projet)}
          </div>
          <h3 style="margin:0 0 8px 0;color:#9A3412;font-size:15px;line-height:1.4;font-weight:800;">
            ${escapeHtml(item.point)}
          </h3>
          <p style="margin:0 0 8px 0;color:#7C2D12;font-size:14px;line-height:1.6;">
            Raison : ${escapeHtml(item.raison)}
          </p>
          <p style="margin:0;color:#9A3412;font-size:14px;line-height:1.6;font-weight:700;">
            Prochaine action : ${escapeHtml(item.prochaine_action_recommandee)}
          </p>
        </td>
      </tr>
      <tr><td style="height:10px;"></td></tr>
    `).join('')
  : emptyBlock('Aucun point non clôturé détecté.');

const actionsHtml = actions.length
  ? actions.map(item => {
      const badge = priorityColor(item.priorite);
      return `
        <tr>
          <td style="padding:16px;background:#FFFFFF;border:1px solid #E2E8F0;border-radius:16px;">
            <div style="margin-bottom:10px;">
              ${projectBadge(item.projet)}
              <span style="display:inline-block;margin-left:6px;padding:6px 10px;border-radius:999px;background:${badge.bg};color:${badge.color};border:1px solid ${badge.border};font-size:12px;font-weight:700;">
                Priorité ${escapeHtml(badge.label)}
              </span>
            </div>
            <p style="margin:0 0 8px 0;color:#0F172A;font-size:15px;line-height:1.6;font-weight:800;">
              ${escapeHtml(item.tache)}
            </p>
            <p style="margin:0;color:#475569;font-size:14px;line-height:1.6;">
              Responsable : <strong>${escapeHtml(item.responsable || 'Non attribué')}</strong><br>
              Échéance suggérée : ${escapeHtml(item.echeance_suggeree || 'Non précisée')}
            </p>
          </td>
        </tr>
        <tr><td style="height:10px;"></td></tr>
      `;
    }).join('')
  : emptyBlock('Aucune action prioritaire détectée.');

const majMemoireHtml = majMemoire.length
  ? majMemoire.map(item => `
      <tr>
        <td style="padding:16px;background:#F8FAFC;border:1px solid #CBD5E1;border-radius:16px;">
          <div style="margin-bottom:10px;">
            ${projectBadge(item.projet)}
            <span style="display:inline-block;margin-left:6px;padding:6px 10px;border-radius:999px;background:#F1F5F9;color:#334155;font-size:12px;font-weight:700;">
              Confiance : ${escapeHtml(item.niveau_confiance || 'Non précisé')}
            </span>
          </div>
          <p style="margin:0 0 8px 0;color:#0F172A;font-size:14px;line-height:1.6;">
            Champ proposé : <strong>${escapeHtml(item.champ_a_modifier)}</strong>
          </p>
          <p style="margin:0 0 8px 0;color:#475569;font-size:14px;line-height:1.6;">
            Nouvelle valeur proposée : ${escapeHtml(item.nouvelle_valeur_proposee)}
          </p>
          <p style="margin:0;color:#64748B;font-size:13px;line-height:1.5;">
            Raison : ${escapeHtml(item.raison)}
          </p>
        </td>
      </tr>
      <tr><td style="height:10px;"></td></tr>
    `).join('')
  : emptyBlock('Aucune mise à jour mémoire proposée.');

const subject = recap.objet_mail || `Récap Direction IA — ${recap.date || ''}`;

const html = `
<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <title>${escapeHtml(subject)}</title>
</head>
<body style="margin:0;padding:0;background:#F1F5F9;font-family:Arial,Helvetica,sans-serif;color:#0F172A;">
  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background:#F1F5F9;margin:0;padding:0;">
    <tr>
      <td align="center" style="padding:28px 12px;">
        <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="max-width:760px;background:#FFFFFF;border-radius:24px;overflow:hidden;border:1px solid #E2E8F0;box-shadow:0 14px 40px rgba(15,23,42,0.08);">

          <tr>
            <td style="padding:34px 28px;background:linear-gradient(135deg,#2563EB 0%,#0EA5E9 100%);">
              <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0">
                <tr>
                  <td>
                    <p style="margin:0 0 8px 0;color:#DBEAFE;font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;">
                      Scribe IA · Rapport quotidien
                    </p>
                    <h1 style="margin:0;color:#FFFFFF;font-size:28px;line-height:1.2;font-weight:900;">
                      ${escapeHtml(recap.titre || 'Récap Direction IA')}
                    </h1>
                    <p style="margin:12px 0 0 0;color:#E0F2FE;font-size:15px;line-height:1.6;">
                      Date : ${escapeHtml(recap.date || '')}
                    </p>
                  </td>
                </tr>
              </table>
            </td>
          </tr>

          <tr>
            <td style="padding:28px;">
              <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0">

                <tr>
                  <td style="padding:18px 18px;background:#F8FAFC;border:1px solid #E2E8F0;border-radius:18px;">
                    <p style="margin:0 0 8px 0;color:#2563EB;font-size:13px;font-weight:800;text-transform:uppercase;letter-spacing:0.06em;">
                      Résumé exécutif
                    </p>
                    <p style="margin:0;color:#334155;font-size:15px;line-height:1.7;">
                      ${escapeHtml(recap.resume_executif || 'Aucun résumé disponible.')}
                    </p>
                  </td>
                </tr>

                ${sectionTitle('Discussion du jour', 'Sujets réellement abordés dans les vocaux et notes du jour.')}
                ${discussionsHtml}

                ${sectionTitle('Points d’évolution notés', 'Idées, stratégies ou avancées détectées.')}
                ${evolutionsHtml}

                ${sectionTitle('Concordance des idées & suggestions IA', 'Analyse par rapport à l’objectif et à l’avancement des projets.')}
                ${concordanceHtml}

                ${sectionTitle('Points à aborder non clôturés', 'Questions ouvertes, zones floues ou sujets à reprendre.')}
                ${nonCloturesHtml}

                ${sectionTitle('Actions prioritaires', 'Tâches concrètes recommandées pour garder le momentum.')}
                ${actionsHtml}

                ${sectionTitle('Mises à jour mémoire proposées', 'Changements suggérés pour la base Projets_Memoire.')}
                ${majMemoireHtml}

                <tr>
                  <td style="padding:24px 18px;background:#0F172A;border-radius:18px;">
                    <p style="margin:0 0 8px 0;color:#93C5FD;font-size:13px;font-weight:800;text-transform:uppercase;letter-spacing:0.06em;">
                      Conclusion direction
                    </p>
                    <p style="margin:0;color:#E2E8F0;font-size:15px;line-height:1.7;">
                      ${escapeHtml(recap.conclusion_direction || 'Aucune conclusion disponible.')}
                    </p>
                  </td>
                </tr>

                <tr>
                  <td style="padding:22px 0 0 0;text-align:center;">
                    <p style="margin:0;color:#94A3B8;font-size:12px;line-height:1.5;">
                      Rapport généré automatiquement par Scribe IA.
                    </p>
                  </td>
                </tr>

              </table>
            </td>
          </tr>

        </table>
      </td>
    </tr>
  </table>
</body>
</html>
`;

const text = `
${recap.titre || 'Récap Direction IA'} - ${recap.date || ''}

Résumé exécutif :
${recap.resume_executif || ''}

Conclusion :
${recap.conclusion_direction || ''}
`;

return [
  {
    json: {
      subject,
      html,
      text,
      recap_json: recap
    }
  }
];

const recap = $json;

const proposals = Array.isArray(recap.maj_memoire_proposees)
  ? recap.maj_memoire_proposees
  : [];

if (!proposals.length) {
  return [];
}

return proposals
  .filter(item => {
    return (
      item.projet &&
      item.champ_a_modifier &&
      item.nouvelle_valeur_proposee
    );
  })
  .map((item, index) => {
    return {
      json: {
        id: `mem_${Date.now()}_${index}`,
        date: recap.date || new Date().toLocaleDateString('fr-FR', { timeZone: 'Europe/Paris' }),
        projet: item.projet || '',
        champ_a_modifier: item.champ_a_modifier || '',
        ancienne_valeur_resume: item.ancienne_valeur_resume || '',
        nouvelle_valeur_proposee: item.nouvelle_valeur_proposee || '',
        raison: item.raison || '',
        niveau_confiance: item.niveau_confiance || 'moyen',
        validation_humaine_recommandee: item.validation_humaine_recommandee === false ? 'non' : 'oui',
        statut: 'À valider',
        validated_by: '',
        decision: '',
        source_recap_date: recap.date || '',
        applique_le: ''
      }
    };
  });
